  "dlgBiblioteka.kliknijElementZebyWstawic": "Click an element to insert it in the center of the page, or drag it onto the page.",
  "dlgCzcionki.czcionki": "Fonts",
  "dlgCzcionki.makietka": ".makietka",
  "dlgCzcionki.mojeCzcionkiZInnych": "My fonts from other projects",
  "dlgCzcionki.oficjalnyZestawAplikacjiTen": "The app's official set – the same for all projects and all users. These fonts are in the list in every project, get embedded in the PDF, and their files can be downloaded (e.g. for the printer or a designer). All are licensed under the SIL Open Font License – they may be used in commercial print.",
  "dlgCzcionki.wlasneCzcionkiProjektu": "Custom project fonts",
  "dlgCzcionki.zestawCzcionekMakietki": "Makietka font set",
  "dlgDostepAi.sztucznaInteligencja": "Artificial intelligence",
  "dlgDostepAi.zamknij": "Close",
  "dlgInstalacjaIos.doEkranuPoczatkowego": "Add to Home Screen",
  "dlgInstalacjaIos.dodaj": "Add",
  "dlgInstalacjaIos.naIphonieIIpadzie": "On iPhone and iPad, the app is added from the Safari menu – then you open it from the home screen, full screen.",
  "dlgInstalacjaIos.rozumiem": "Got it",
  "dlgInstalacjaIos.udostepnij": "Share",
  "dlgInstrukcja.zamknijInstrukcje": "Close guide",
  "dlgKoloryDruku.drukKolorow": "Color printing",
  "dlgKoloryDruku.farbaMieszanaOsobnoNp": "An ink mixed separately, e.g. Pantone – in the PDF it's a separate plate. Enter the name as given by the printer or the swatch book; the CMYK next to it is only for on-screen preview. You can also add a new spot color right at the element – in the color picker or in Properties → “Print finish”.",
  "dlgKoloryDruku.gotowe": "Done",
  "dlgKoloryDruku.koloryDodatkoweNpPantone": "Spot colors (e.g. Pantone)",
  "dlgKoloryDruku.koloryUzyteWProjekcie": "Colors used in the project and how they'll go to print. Set them for the whole project or separately for one section – e.g. a full-color cover and a black-and-white body.",
  "dlgKoloryDruku.lakierZlocenieTloczenieI": "Varnish, foil, embossing and white are set on the element: select it and choose Properties → “Print finish”. Here you can see what's in the project.",
  "dlgKoloryDruku.rozszerzonyCmykIInne": "Extended CMYK and other inks",
  "dlgKoloryDruku.rozszerzonyCmykNpCmyk": "Extended gamut CMYK (e.g. CMYK + orange, green and violet) is done by the printer from your file – no separate palette needed. White, varnish, foil and embossing go into the PDF as separate plates with an overlay (so the printer can see where to apply them).",
  "dlgKoloryDruku.wykonczeniaDruku": "Print finishes",
  "dlgKoloryDruku.zamknij": "Close",
  "dlgKomentarze.moje": "Mine",
