  "dlgKontrola.sprawdzPrzedDrukiem": "Preflight check",
  "dlgKontrola.uwagiDoCalegoProjektu": "Notes for the whole project, after series are expanded: empty fields, missing images, duplicates, missing data and text that doesn't fit its frames.",
  "dlgListaKolumny.anuluj": "Cancel",
  "dlgListaKolumny.komorkiZInnaWartoscia": "Cells with a different value are highlighted and added to the “Preflight check” list. In the data template, cells in this column get a drop-down list.",
  "dlgListaKolumny.wartosciKazdaWOsobnym": "Values – each on a separate line or separated by semicolons",
