  "eksportSerii.szablonIDaneDla": "Template and data for Scribus with the ScribusGenerator plugin (mail merge).\n\nFiles:\n  szablon.sla – project pages, each once; fields are replaced by the variables {pola}\n  dane.csv    – data (UTF-8, comma); image columns contain paths obrazy/…\n  obrazy/     – images from the data\n\nIn Scribus: Script → Execute Script → ScribusGenerator, choose szablon.sla and dane.csv, separator “,”.\nThe %VAR_column% variables in texts will be replaced with values from successive rows.",
  "eksportSerii.szablonIDaneDo": "Template and data for mail merge in Word (and also in Publisher, for those who still have it).\n\nFiles:\n  szablon.docx – project pages with layout (text frames, images, shapes in place) and merge fields {pola}\n  dane.xlsx    – data (sheet “Dane”); the same in dane.csv\n\nWord: open szablon.docx → Mailings → Select Recipients → Use an Existing List → dane.xlsx →\n  Finish & Merge. The fields are already in the text (MERGEFIELD).\nPublisher: Mailings → Mail Merge → Use an Existing List → dane.xlsx, then insert fields from the list.\n\nText frames are Word text boxes anchored to the page – after merging, each data row is another page\nwith the same layout. Tables, calendars and elements with effects are images.",
  "eksportTekstu.spisTresci": "Contents",
  "emailInny.wpiszInnyAdres": "Enter a different address",
