  "kontrola.czescWystajePoZamknieciu": "Part {nazwa} sticks out by {round} mm when the pop-up card is closed – shorten it or move the glue areas closer to the spine.",
  "kontrola.i": "{join} and {x} {x|other|others}",
  "kontrola.jedenWierszToJedna": "One row is one page; the series block has {n} {n|page|pages}.",
  "kontrola.jedenWierszToJedno": "One row is one repetition of the block ({n} {n|page|pages}).",
  "kontrola.kartkaPopUpNie": "The pop-up card {nazwa} doesn't close flat – the glued parts jam (a platform strip or V-fold arm of a different length than the distance between glue areas). Fix the lengths or the glue areas.",
  "kontrola.kolorPoPrzeliczeniuNa": "Color {k} converted to CMYK gives {tac}% ink coverage (above {LIMIT_TAC}%) – the print shop may ask for a lighter color or a plain black.{x} Check it in the separations preview.",
  "kontrola.liniaCieciaZOtwartej": "Cut line made from an open line – the knife will cut only that segment. If it's the outline of a piece to cut out, draw it as a closed shape (rectangle, polygon, closed pen shape). {size|Page|Pages} {lista}.",
  "kontrola.liniaZgieciaAlboMiejsce": "A fold line or glue area lies outside the die line – it will be gone after cutting. Move it onto the cut piece. {size|Page|Pages} {lista}.",
  "kontrola.nieMaWProjekcie": "The project has no image “{plik}” (column “{kolumna}”) – {size|page|pages} {lista}.",
  "kontrola.niejednoznacznaNazwaObrazuKolumna": "Ambiguous image name “{plik}” (column “{kolumna}”): several files match ({pasuja}) – add the extension in the table. {size|Page|Pages} {lista}.",
  "kontrola.nowyWierszCo": "a new row every {co} {co|page|pages}",
  "kontrola.nowyWierszGdyZmieni": "a new row when the column {join} changes",
  "kontrola.nowyWierszGdyZmieni2": "a new row when the column “{x}” changes",
  "kontrola.odsylaczProwadziDoElementu": "A cross-reference points to an element that no longer exists (“?” shows instead of the page number): {join}. Insert the cross-reference again.",
  "kontrola.okladkaJestZOkleiny": "The cover “{nazwa}” is made of cover material ({opisWykonczenia}): its artwork isn't printed. Only foiled or embossed elements stay on the cover material – send the print shop the finishes file (PDF export → finishes separately) and the specification (⋯ menu → Print specification).",
  "kontrola.okladkaMaZaokragloneRogi": "The cover “{nazwa}” has rounded corners ({rogi_mm} mm) – don't place important elements in the corners; note it in the order (Print specification).",
  "kontrola.oprawaZeszytowaSrodekMa": "Saddle stitch: the inside has {stron} pages, but the count must be divisible by 4.",
  "kontrola.poleNieMaSkad": "The field {nazwa} has nowhere to get its value from (no such column or document field) – {size|page|pages} {lista}.",
  "kontrola.przezroczyste": "transparent",
  "kontrola.saLinieZgieciaAlbo": "There are fold lines or glue areas but no cut line – the fold-up can't be cut out. Mark the piece outline as “Cutting” (Print colors → Finish). {size|Page|Pages} {lista}.",
  "kontrola.sekcjaJestNaBiale": "The section “{nazwa}” is on {podloze}: white elements won't print (white means no ink) – they will come out {x}. Give them a white underprint (Print colors → Finish) or a different color. {size|Page|Pages} {lista}.",
  "kontrola.sekcjaJestNaPrzezroczystej": "The section “{nazwa}” is on transparent film, and no element has a white underprint – colors will show through. If they should be opaque, put a white underprint under them.",
  "kontrola.sekcjaMaDoPelnej": "The section “{nazwa}” has {stron} {stron|page|pages} – {brakuje} short of a full signature of {skladka}. Add pages or use “Fill with blanks” in the page list.",
  "kontrola.seriaOdStronyStrony": "Series “{nazwa}”: from page {zamianaOd} on, block pages land on the opposite side of the spread than in the page layout (left on the right, right on the left). Check “Keep left and right pages” in the series window, and a blank page will be inserted there.",
  "kontrola.seriaPowielaSieRazy": "The series “{nazwa}” repeats {ile} times, but the table has {zDanymi} {zDanymi|row|rows}{x} – values will start repeating.",
  "kontrola.seriaTabelaMaA": "Series “{nazwa}”: the table “{nazwa2}” has {jest} {jest|row|rows}, but {potrzeba} are needed ({opisKroku}). From page {brakOd}{x} on, its fields will be empty.",
  "kontrola.seriaTabelaMaA2": "Series “{nazwa}”: the table has {wierszy} {wierszy|row|rows} and the block {dlugosc} {dlugosc|page|pages} – the last repetition is filled out with pages without data.",
  "kontrola.seriaWszystkieWierszeTabeli": "Series “{nazwa}”: all table rows are skipped ({ZNACZNIK_POMIJANIA}) – the series produces no pages.",
  "kontrola.seriaZebyStronyLewe": "Series “{nazwa}”: {ile|a blank page was inserted|blank pages were inserted} ({ile|page|pages} {lista}) so that left pages stay on the left and right pages on the right. A blank page is white and counts in the numbering.",
