  "skladankaSzablony.jednaCzescPasCzterech": "One part: a band of four walls, a lid and a bottom, glue tabs.",
  "skladankaSzablony.kartkaIPasekPrzyklejony": "A card and a strip glued with tabs on both sides of the spine – when open it stands like a box, when closed it lies flat inside.",
  "skladankaSzablony.klinyOdBiegunaDo": "Gores from pole to pole (4–24) – each one glues to the next with tabs; the more gores, the rounder.",
  "skladankaSzablony.mechanizmWiekoNaZawiasie": "Mechanism: a hinged lid with a tongue tucked behind the front wall – opens and closes without glue.",
  "skladankaSzablony.mechanizmWiekoZJezykiem": "Mechanism: a lid with a tongue that slides into a slot in the front wall – it snaps shut (the slot is sized to the material thickness).",
  "skladankaSzablony.mniejszaPlatformaWKacie": "A smaller platform in the angle between the first one and the card: {d2} mm at the platform, {d1} mm at the card.",
  "skladankaSzablony.nacieciaCzerwonePrzetnijZegnij": "Cut the (red) slits, fold along the lines and open the card at a right angle – {x} by {r2} mm.",
  "skladankaSzablony.nadwozieZMaskaKabina": "Car body with hood, cabin and trunk – a solid from the silhouette, unfolded automatically (draw the wheels or glue them on separately).",
  "skladankaSzablony.narysujTuToCo": "Draw here what the flaps cover, and glue the card on top – glue only outside the windows.",
  "skladankaSzablony.okienkaWycieteZTrzech": "Windows cut on three sides and folded on the fourth (the hinge) – underneath, a second card with a hidden picture.",
  "skladankaSzablony.ostroslupOWysokosciMm": "Pyramid {r2} mm high from a polygon ({n} sides).",
  "skladankaSzablony.pasScianIDwie": "A band of walls and two bases at the first wall.",
  "skladankaSzablony.plaszczWycinekKolaZ": "Side wall – a circle sector – with tabs to the bottom; the unfolding angle is calculated from the height and diameter.",
  "skladankaSzablony.plaszczWycinekPierscieniaZ": "Side wall – a ring sector – with tabs to the bottom and lid.",
  "skladankaSzablony.plaszczZZakladkamiDo": "Side wall with tabs to the bottom and lid (circles made of many short sides – they match the tabs in length).",
  "skladankaSzablony.podstawaITrojkatyScian": "Base with triangular faces around it; a tab on each triangle.",
  "skladankaSzablony.polDoZadrukuW": "{n} fields to print; a cross for the brad in the middle.",
  "skladankaSzablony.profilObroconyWSegmentach": "Profile revolved in segments (6–32): bands of walls with tabs and a flat bottom – unfolded automatically; open top.",
  "skladankaSzablony.przetnijNacieciePrzyPrawym": "Cut the slit at the right edge and thread the strip through it from below – the wide end stays under the card.",
  "skladankaSzablony.przetnijTrzyBokiKazdej": "{n} {x}: cut three sides of each (red), fold the fourth – that's the hinge.",
  "skladankaSzablony.pudelkaWyskocza": "the boxes will pop out",
  "skladankaSzablony.pudelkoWyskoczy": "the box will pop out",
  "skladankaSzablony.ramieMmKatDo": "Arm {r2} mm, angle {r22}° to the spine.",
  "skladankaSzablony.ruchMmUchwytWystaje": "Travel {r2} mm; the handle sticks out beyond the card.",
  "skladankaSzablony.scianyIDachJako": "Walls and roof as one solid, unfolded automatically – gables, roof slopes and walls with tabs and numbers.",
  "skladankaSzablony.scianyWysokosciMmZ": "Walls {r2} mm high with a bottom; the tabs at the top go under the roof.",
  "skladankaSzablony.skorupaZSegmentowGlowa": "A shell made of segments, a head, four legs and a tail – solids unfolded automatically; glue the head, legs and tail under the shell.",
  "skladankaSzablony.trojkatPrzyklejonySkosniePo": "A triangle glued diagonally on both sides of the spine – it lies flat when the card is open, and rises and folds inside when the card closes.",
  "skladankaSzablony.wiekoNaZawiasieJezyk": "Hinged lid with a tuck flap behind the front wall – opens and closes without glue.",
  "skladankaSzablony.wiekoNaZawiasieJezyk2": "Hinged lid with a tuck flap that slides into a slot in the front wall – snaps shut.",
  "skladankaSzablony.wytnijOkienkoPrzebijSrodek": "Cut out the window, pierce the center of both discs and join them with a brad – the top one turns over the bottom one.",
  "skladankaSzablony.zegnijGrzbietWDoline": "Valley-fold the spine; glue the triangle by its tabs to the slanted areas with the same numbers.",
  "skladankaSzablony.zegnijLukiBigPo": "Fold the arcs (crease along the arc) and push the ends inward – they close by themselves.",
  "skladankaSzablony.zegnijWDolineNa": "Valley-fold along the spine; glue the strip by its tabs to the glue areas with the same numbers.",
  "skladankaSzablony.zwinKatRozwinieciaSklej": "Roll it up (unrolled angle {r2}°), glue tab “c”, then the bottom and the lid.",
  "skladankaSzablony.zwinWRurkeObwod": "Roll it into a tube (circumference {r2} mm), glue tab “c”, then the tabs to the bases.",
  "skladankaSzablony.zwinWStozekKat": "Roll it into a cone (unrolled angle {r2}°), glue tab “c”, then glue it to the bottom.",
